window.A2_UNITS.push(
{ n:9, title:"CONTRAST", classes:"37–38", node:"node/09_contrast", color:"#d94f45", theme:"Then, now, next — and what happens if",
  overview:{
    intro:"This node puts three time frames in the same paragraph so you can talk about change, and then introduces the first conditional: the grammar of consequences. Both structures depend on the same skill — keeping each clause in the tense its job requires.",
    goals:["Contrast past, present and future in one connected description of change.","Build first conditional sentences with if + present simple and will in the main clause.","Use unless, as long as and in case correctly inside conditional sentences."],
    outcome:"By the end you can describe how your life or your city has changed across three time frames, and explain the consequences of a real decision."
  },
  vocab:[
    {term:"to used to be like", pos:"pattern", def:"asking or saying what something was like before.",
     use:"“What did it use to be like?” is the standard question about a past state. Answer with “used to be + adjective”.",
     examples:["What did your neighbourhood use to be like?","It used to be much quieter."],
     colloc:"what was it like · it used to be · not like it used to be"},
    {term:"nowadays", pos:"adverb", def:"in the present, in contrast with the past.",
     use:"Usually at the beginning or end of the sentence and always with a present tense: “Nowadays everyone works remotely.”",
     examples:["Nowadays most people pay with their phones.","People used to write letters; nowadays they text."],
     colloc:"nowadays · these days · not nowadays"},
    {term:"to expect", pos:"verb", def:"to believe something will happen.",
     use:"“Expect + to + verb” or “expect that…”: “I expect to finish by six.” Not the same as “wait for”, which is physical.",
     examples:["I expect prices will keep rising.","We weren’t expecting so many people."],
     colloc:"expect a change · as expected · better than expected"},
    {term:"unless", pos:"conjunction", def:"if not; except if.",
     use:"Already negative, so the verb after it stays positive: “unless you pay” = “if you don’t pay”. Never “unless you don’t pay”.",
     examples:["Unless we leave now, we’ll miss the train.","I won’t say anything unless she asks."],
     colloc:"unless you · not unless · unless something changes"},
    {term:"as long as", pos:"conjunction", def:"only on the condition that.",
     use:"Followed by a present tense with future meaning: “as long as you tell me first”. Synonym: “provided that” (more formal).",
     examples:["You can borrow it as long as you return it tomorrow.","It’s fine as long as nobody complains."],
     colloc:"as long as you like · just as long as · so long as"},
    {term:"consequence", pos:"noun", def:"the result of an action, usually a serious one.",
     use:"“As a consequence of + noun” or “the consequences of + noun”. More neutral synonym: “result”.",
     examples:["There will be consequences if we ignore this.","As a consequence, the project stopped."],
     colloc:"serious consequences · face the consequences · as a consequence"},
    {term:"to improve", pos:"verb", def:"to get better, or make something better.",
     use:"Works with and without an object: “My English has improved” and “I want to improve my English”.",
     examples:["Traffic has improved since they opened the new road.","How can we improve the process?"],
     colloc:"improve rapidly · a big improvement · improve on it"},
    {term:"trend", pos:"noun", def:"a general direction of change over time.",
     use:"“A trend towards + noun/-ing”: “a trend towards working from home”. Adjective: “trendy” (fashionable) is different.",
     examples:["There’s a clear trend towards online study.","The trend is likely to continue."],
     colloc:"a growing trend · reverse the trend · current trends"},
    {term:"in case", pos:"conjunction", def:"as a precaution, because something might happen.",
     use:"Never with “will”: “Take an umbrella in case it rains.” Not the same as “if” — it means you act before knowing.",
     examples:["Save the file in case the laptop crashes.","I’ll take cash in case the card doesn’t work."],
     colloc:"just in case · in case of emergency"},
    {term:"gradually", pos:"adverb", def:"slowly, over a period of time.",
     use:"Common in descriptions of change, usually before the verb: “Things gradually got better.”",
     examples:["The situation gradually improved.","I gradually got used to the schedule."],
     colloc:"gradually increase · gradually disappear"} ],
  grammar:[
    {name:"Time contrast: past, present, future", short:"I used to… now I… and next year I’m going to…",
     rule:"To describe change you need three tenses working in the same paragraph: a past form for what is no longer true, a present form for the current situation, and a future form for what comes next. The connectors mark the shift so your listener follows the movement.",
     form:["Past: used to + verb / simple past → I used to commute two hours a day.","Present: present simple or present continuous → Now I work from home.","Future: be going to / will → Next year I’m going to move closer to the office.","Change connectors: but now, these days, nowadays, at the moment, in the future, from now on, by next year."],
     notes:["Keep the subject and the topic constant while you change the tense; the contrast is only visible if everything else stays the same.","“Now” and “nowadays” pull a present tense; “used to” and “back then” pull a past; “next year” and “soon” pull a future. Let the marker choose the verb.","The present perfect belongs in this paragraph too, as the bridge between past and present: “Things have changed a lot since then.”","Do not mix “used to” with a present marker: “Nowadays I used to work at home” is a contradiction.","In writing, one connector per shift is enough — three “nowadays” in a paragraph sounds mechanical."],
     deep:"This is less a new structure than a discipline: managing tense across a whole paragraph instead of one sentence. Most learners can produce each form in isolation and then lose control when the frames alternate, because every clause needs its own time anchor. A practical method is to build the paragraph as a table before you speak: column one, what was true; column two, what is true; column three, what will be true. Then say each row with the same subject. Notice that the present perfect is the natural hinge between the first two columns, because its whole job is to link a past event to the present situation — “I used to smoke, I’ve stopped now, and I’m going to run a 10K in June” is a complete story in three tenses. English also expects a visible connector at each shift; without “but now” or “these days”, a listener may hear your present sentence as part of the past narration.",
     chart:{title:"One topic, three time frames", cols:["Frame","Form","Example"], rows:[["Then","used to / simple past","I used to work in an office."],["Bridge","present perfect","Things have changed since the pandemic."],["Now","present simple / continuous","These days I work from home."],["Soon","be going to / present continuous","Next month I’m starting a hybrid schedule."],["Prediction","will","I think remote work will keep growing."]]},
     examples:["Ten years ago this street used to be full of shops; now most of them are gone.","I didn’t use to read much, but these days I finish a book a month.","We’ve improved the process a lot, and next quarter we’re going to automate it.","Back then nobody had a smartphone. Nowadays we can’t live without one."],
     watch:"Every clause needs its own time marker and its own tense — do not let one tense run through the whole paragraph."},
    {name:"Conditional sentences with if clauses (first conditional)", short:"If it rains, we’ll cancel.",
     rule:"The first conditional talks about a real, possible future. The if-clause states the condition in the present simple; the main clause states the consequence with will, going to, an imperative or a modal. As in time clauses, “will” never appears after “if” in this pattern.",
     form:["If + present simple, will + base verb → If you send it today, they’ll reply tomorrow.","Reversed order, no comma: They’ll reply tomorrow if you send it today.","Other main clauses: If you finish early, call me. / If it rains, we might stay home.","Unless = if not → Unless you hurry, you’ll be late.","As long as / provided that = only on this condition → You can come as long as you behave."],
     notes:["“If I will…” is the classic error. The condition takes the present simple: “If I have time, I’ll help you.”","A comma separates the clauses only when the if-clause comes first.","“If” means it may or may not happen; “when” means it certainly will: “If I see her, I’ll tell her” vs “When I see her, I’ll tell her.”","“Unless” is inherently negative, so keep the verb after it positive: “unless you tell me”, not “unless you don’t tell me”.","The zero conditional (if + present, present) is for general truths: “If you heat water to 100°, it boils.” Same shape, different meaning."],
     deep:"A conditional sentence is a small machine with two slots: the condition and the consequence. English keeps the machine honest by marking the future only once, in the consequence slot, which is why the condition slot takes a present tense even though it points forward. Once you accept that, the first conditional becomes a flexible tool rather than a formula, because you can change the consequence to fit your intention: “will” for a prediction, “going to” for a plan, an imperative for an instruction (“If it breaks, call me”), and a modal for degrees of possibility (“If she asks, I might tell her”). The choice between “if”, “when” and “unless” carries real information about your certainty, and mixing them up will genuinely mislead a listener — “when you finish” tells your colleague you assume the task will be done; “if you finish” quietly suggests you doubt it. Later nodes will move this same machine into the unreal past (node 15); the shape you learn here is the foundation of all of it.",
     chart:{title:"First conditional variations", cols:["If-clause","Main clause","Meaning"], rows:[["If it rains,","we’ll stay home.","prediction"],["If you’re late,","we’re going to start without you.","plan"],["If the light turns red,","stop.","instruction"],["If she calls,","I might answer.","possibility"],["Unless you book now,","you won’t get a seat.","if not"],["As long as you pay,","you can stay.","only condition"]]},
     examples:["If I finish the report today, I’ll take tomorrow off.","We won’t get tickets unless we book this week.","If the payment doesn’t arrive, call the bank immediately.","You can use my laptop as long as you don’t install anything."],
     watch:"No “will” after “if” in a first conditional: “If I have time”, never “If I will have time”."} ],
  speaking:[
    {kind:"Then and now", text:"Describe your city, your job or your habits across three time frames in one minute. Your partner counts your tense shifts and flags any missing connector."},
    {kind:"Domino chain", text:"Start with a condition. Each student turns the previous consequence into a new condition: “If it rains, we’ll stay in. If we stay in, we’ll cook…”"},
    {kind:"Negotiation", text:"Agree the rules for sharing a flat or a project. Every rule must use if, unless or as long as."} ],
  tips:[
    "Let the time marker choose the tense, clause by clause.",
    "“If” = maybe; “when” = certainly. Choose deliberately.",
    "After “unless”, keep the verb positive."],
  quiz:{q:"If the meeting ___ early, I’ll join you for lunch.", options:["finishes","will finish","is going to finish"], answer:0, explain:"The if-clause of a first conditional takes the present simple; only the main clause carries the future."} },

{ n:10, title:"PREFERENCE", classes:"41–42", node:"node/10_preference", color:"#5b8def", theme:"Likes, dislikes and the reasons behind them",
  overview:{
    intro:"What you enjoy, what you can’t stand, and why. This node combines gerunds after verbs of liking with the short responses that keep a conversation alive, and then gives you the machinery for stating reasons with “because” and its relatives.",
    goals:["Use gerunds after like, love, enjoy, hate, don’t mind and can’t stand.","Agree and disagree with short responses: so do I, neither do I, I do, I don’t.","Give reasons with because, because of, since and so."],
    outcome:"By the end you can hold a five-turn conversation about preferences, reacting to your partner instead of just listing your own tastes."
  },
  vocab:[
    {term:"to enjoy", pos:"verb", def:"to get pleasure from something.",
     use:"Always followed by a noun or -ing, never an infinitive: “I enjoy cooking”, not “I enjoy to cook”. It also needs an object: “Did you enjoy it?”",
     examples:["I really enjoy working with this team.","She enjoyed the concert."],
     colloc:"enjoy yourself · thoroughly enjoy · enjoy doing something"},
    {term:"can’t stand", pos:"expression", def:"to hate something intensely.",
     use:"“Can’t stand + -ing” or a noun: “I can’t stand waiting in queues.” Stronger than “don’t like”.",
     examples:["I can’t stand being interrupted.","He can’t stand the heat."],
     colloc:"can’t stand it · really can’t stand · can’t stand doing"},
    {term:"to don’t mind", pos:"expression", def:"to be fine with something; to have no objection.",
     use:"“I don’t mind + -ing”: “I don’t mind working late.” Positive “I mind” is rare; use “it bothers me”.",
     examples:["I don’t mind cooking if someone else cleans.","Do you mind if I sit here?"],
     colloc:"I don’t mind at all · never mind · would you mind"},
    {term:"to be into", pos:"expression", def:"to be very interested in something (informal).",
     use:"“Be into + noun / -ing”: “I’m into climbing.” Informal but extremely common in spoken English.",
     examples:["She’s really into photography.","I’m not into video games."],
     colloc:"really into · not into it · what are you into"},
    {term:"to prefer", pos:"verb", def:"to like one thing more than another.",
     use:"Two patterns: “prefer + -ing to + -ing” (I prefer walking to driving) and “prefer + to + verb” (I prefer to walk).",
     examples:["I prefer working mornings to working nights.","Would you prefer to meet on Friday?"],
     colloc:"prefer not to · a personal preference · prefer A to B"},
    {term:"neither", pos:"adverb / determiner", def:"not one and not the other.",
     use:"In short responses it needs inversion: “Neither do I”, “Neither am I”. It carries the negative, so the verb stays positive.",
     examples:["I don’t like horror films. — Neither do I.","Neither of them answered."],
     colloc:"neither do I · neither of us · me neither"},
    {term:"reason", pos:"noun", def:"the explanation for something.",
     use:"“The reason for + noun” or “the reason why + clause”: “the reason for the delay”, “the reason why I left”.",
     examples:["The main reason is the price.","There’s no reason to worry."],
     colloc:"the main reason · for that reason · no reason at all"},
    {term:"because of", pos:"preposition", def:"used before a noun to give the cause.",
     use:"“Because of + noun”, “because + full clause”. “Because of the rain” vs “because it rained”.",
     examples:["We cancelled because of the weather.","She left early because of a family problem."],
     colloc:"because of you · mainly because of · because of that"},
    {term:"boring / bored", pos:"adjectives", def:"“boring” describes the thing; “bored” describes the person.",
     use:"The -ing/-ed pair covers many feelings: interesting/interested, tiring/tired, confusing/confused. Full treatment at node 13.",
     examples:["The film was boring, so I got bored.","I’m bored of doing the same thing."],
     colloc:"deadly boring · get bored · bored to death"},
    {term:"to be worth it", pos:"expression", def:"good enough to justify the effort or cost.",
     use:"“It’s worth + -ing” or “it’s worth it”: “The extra hour was worth it.”",
     examples:["The course was expensive, but it was worth it.","It’s worth trying at least once."],
     colloc:"well worth it · not worth it · worth every penny"} ],
  grammar:[
    {name:"Gerunds and short responses", short:"I love cooking. — So do I. / I don’t. ",
     rule:"Verbs of liking and disliking are followed by the gerund (-ing) when the object is an activity. In conversation, agreement and disagreement are expressed with a short response that repeats only the auxiliary — never the whole sentence.",
     form:["Verb + -ing: like, love, enjoy, hate, don’t mind, can’t stand, prefer → I hate waiting.","Agreeing with a positive: So do I. / Me too. / So am I. / So did we.","Agreeing with a negative: Neither do I. / Me neither. / Neither am I.","Disagreeing with a positive: I don’t. / Oh, I do. / Really? I don’t.","Disagreeing with a negative: I do. / Oh, I do."],
     notes:["“So” and “neither” both require inversion: “So do I”, “Neither have I” — never “So I do”.","The auxiliary in the response must match the original sentence: “I’m tired” → “So am I”; “I went” → “So did I”; “I’ve finished” → “So have I”.","“Me too” and “me neither” are informal but perfectly acceptable in speech; they never change form.","“Like + to + verb” is also correct and slightly more about habit or choice: “I like to get up early” (my policy) vs “I like getting up early” (I enjoy it).","“Would like” is different from “like”: it means “want” and always takes an infinitive — “I’d like to order”."],
     deep:"There are two skills here and the second one is what makes you sound like a participant rather than a speaker of prepared sentences. The gerund rule itself is mechanical: after a verb of liking, the activity becomes a noun, so it takes -ing. The response system is more interesting because it is built on echo. English hates repetition, so instead of “I also love cooking”, the language echoes only the grammatical skeleton of what the other person said — the auxiliary — and lets that stand for the whole idea. This means you must listen to the auxiliary, not the content: if your partner said “I’ve never been to Brazil”, your agreement is “Neither have I”, because their sentence was built on “have”. Get into the habit of scanning for the auxiliary while your partner is still speaking, and remember that when a sentence has no auxiliary, the response borrows “do”: “I like it” → “So do I”. The polarity flip is the last piece: “neither” and “me neither” answer a negative, so they need no second negative of their own.",
     chart:{title:"Short response matrix", cols:["Original","Agree","Disagree"], rows:[["I like it.","So do I. / Me too.","I don’t."],["I don’t like it.","Neither do I. / Me neither.","I do."],["I’m tired.","So am I.","I’m not."],["I’ve finished.","So have I.","I haven’t."],["I went alone.","So did I.","I didn’t."],["I can’t swim.","Neither can I.","I can."]]},
     examples:["I can’t stand working late. — Neither can I.","I really enjoy travelling on my own. — Do you? I don’t.","I don’t mind driving at night. — So do I… sorry: neither do I.","I’ve never tried it. — Neither have I."],
     watch:"Match the auxiliary and invert it: “So have I”, “Neither did I”. Never “So I have”."},
    {name:"Clauses with “because”", short:"I left because I was tired. / because of the traffic.",
     rule:"“Because” introduces a full clause with its own subject and verb and answers the question “why?”. “Because of” is a preposition and must be followed by a noun or a gerund. Related connectors change the emphasis or the position of the reason.",
     form:["because + subject + verb → I stayed home because I felt ill.","because of + noun/-ing → I stayed home because of the rain.","since / as + clause (reason known, often first) → Since it was raining, we stayed in.","so + result → It was raining, so we stayed in.","the reason why / the reason for → The reason why I called is simple."],
     notes:["“Because” cannot start a sentence in careful written English on its own; it needs a main clause somewhere: “Because I was tired, I left” is fine, but “Because I was tired.” alone is a fragment.","“Because of” must be followed by a noun phrase: “because of the delay”, not “because of the train was late”.","“So” introduces the consequence, “because” the cause — they are mirror images: “I was tired, so I left” = “I left because I was tired”.","“Since” and “as” present the reason as already known or obvious, and usually come first in the sentence; “because” often carries the new or important information and comes second.","Do not use “for” to mean “because” at this level — it is literary and easily misused."],
     deep:"Cause and consequence are two views of the same relationship, and choosing which one to put in the main clause changes what your listener treats as important. English readers weight the second clause more heavily, so “The flight was cancelled, so we stayed another night” foregrounds the outcome, while “We stayed another night because the flight was cancelled” foregrounds the explanation. Use that deliberately in writing. The grammatical trap is purely mechanical: “because” takes a clause, “because of” takes a noun, and the fastest test is to look at what comes next — if you can see a verb with its own subject, drop the “of”. Watch out for one more thing: over-using “because” makes speech sound like a child explaining. Rotating in “since”, “as”, “so” and “that’s why” gives your reasoning texture, and “the reason why … is that …” is a useful frame when you need to announce that an explanation is coming.",
     chart:{title:"Cause and result connectors", cols:["Connector","Followed by","Example"], rows:[["because","clause","I left because I was tired."],["because of","noun / -ing","I left because of the noise."],["since / as","clause (known reason)","Since you’re here, let’s start."],["so","clause (result)","I was tired, so I left."],["that’s why","clause (result)","I was tired. That’s why I left."],["the reason why … is that","clause","The reason why I left is that I was tired."]]},
     examples:["We changed the date because of a scheduling conflict.","Since nobody replied, I made the decision myself.","The train was delayed, so I missed the first session.","The reason why I prefer mornings is that the office is quiet."],
     watch:"“Because of” + noun, “because” + clause. “Because of it was late” is always wrong."} ],
  speaking:[
    {kind:"Preference ping-pong", text:"Make a statement about something you like or hate. Your partner must respond with a short response (so/neither/I do/I don’t) and add a reason with because. Ten turns without breaking the chain."},
    {kind:"Ranking", text:"In groups, rank five ways of spending a free Sunday. Every argument must contain a gerund and a reason."},
    {kind:"Reason swap", text:"Give a statement with “because”. Your partner rewrites it with “because of”, then with “so”, keeping the meaning."} ],
  tips:[
    "After like, love, hate, enjoy, don’t mind and can’t stand, use -ing.",
    "Listen for the auxiliary — it is what your short response repeats.",
    "“Because of” needs a noun; if you can see a verb, drop the “of”."],
  quiz:{q:"I can’t stand ___ in traffic. — Neither ___ I.", options:["sitting / can","to sit / do","sitting / do"], answer:0, explain:"“Can’t stand” takes the gerund, and the short response repeats the same auxiliary — “can” — after “neither”."} },

{ n:11, title:"BLACK BOX", classes:"46–47", node:"node/11_blackbox", color:"#2fbf9e", theme:"When the action matters more than the actor",
  overview:{
    intro:"Sometimes the interesting part of a sentence is not who did it. The passive voice moves the object into the subject position and pushes the agent to the end — or deletes it entirely. This node covers the past passive with “by” and the present passive without it.",
    goals:["Form the passive with be + past participle in the simple past and simple present.","Decide when to include “by + agent” and when to leave it out.","Convert active sentences into passive ones without losing meaning."],
    outcome:"By the end you can describe a process, a rule and a historical event in the passive, and explain why the passive was the right choice."
  },
  vocab:[
    {term:"to be built", pos:"passive form", def:"constructed by someone.",
     use:"“Build – built – built”. The passive is extremely common with buildings and dates: “It was built in 1890.”",
     examples:["The bridge was built two years ago.","Those flats are being built now."],
     colloc:"was built in · newly built · purpose-built"},
    {term:"to invent", pos:"verb", def:"to create something that did not exist before.",
     use:"Classic passive verb with “by”: “The telephone was invented by Bell.” Noun: invention; person: inventor.",
     examples:["Penicillin was discovered, not invented.","Who invented this system?"],
     colloc:"invent a machine · a new invention · newly invented"},
    {term:"to produce", pos:"verb", def:"to make or grow something, usually in quantity.",
     use:"Standard in present passive descriptions: “Coffee is produced in Huila.” Noun: production, produce (food).",
     examples:["Most of our coffee is produced locally.","The factory produces 2,000 units a day."],
     colloc:"mass-produced · locally produced · production line"},
    {term:"to deliver", pos:"verb", def:"to take goods to a place.",
     use:"Very frequent in the passive: “Your order will be delivered tomorrow.” Noun: delivery.",
     examples:["Packages are delivered every morning.","It was delivered to the wrong address."],
     colloc:"free delivery · deliver on time · be delivered"},
    {term:"to damage", pos:"verb", def:"to harm something physically.",
     use:"Passive with no agent is normal when the cause is unknown: “The screen was damaged in transit.”",
     examples:["Two houses were damaged by the storm.","Nothing was damaged, luckily."],
     colloc:"badly damaged · cause damage · damage control"},
    {term:"to allow", pos:"verb", def:"to permit.",
     use:"The passive is the standard way to state rules: “Smoking is not allowed here.” Compare “permitted” (more formal).",
     examples:["Photos aren’t allowed inside the museum.","Are we allowed to park here?"],
     colloc:"not allowed · allowed to enter · allow access"},
    {term:"agent", pos:"noun (grammar)", def:"the person or thing that performs the action.",
     use:"In a passive sentence the agent appears after “by”, if it appears at all: “written by a student”.",
     examples:["The agent is usually left out when it’s obvious.","This was signed by the director."],
     colloc:"by + agent · the agent is unknown"},
    {term:"to require", pos:"verb", def:"to need officially.",
     use:"Very common in passive rules: “A visa is required.” “Applicants are required to submit…”.",
     examples:["Proof of address is required.","You’re required to sign here."],
     colloc:"required by law · a requirement · as required"},
    {term:"to handle", pos:"verb", def:"to deal with something or someone.",
     use:"“Complaints are handled by the front desk.” Also physical: “Handle with care.”",
     examples:["All requests are handled within 48 hours.","She handled the situation very well."],
     colloc:"handle a complaint · handle with care · easy to handle"},
    {term:"to be based on", pos:"passive expression", def:"to use something as a foundation.",
     use:"Fixed preposition: “based on a true story”, “based in Bogotá” (location). Do not mix “on” and “in”.",
     examples:["The film is based on a real case.","Our team is based in Medellín."],
     colloc:"based on evidence · based in · widely based"} ],
  grammar:[
    {name:"Passive with “by” (simple past)", short:"The report was written by an intern.",
     rule:"The past passive is formed with was / were plus the past participle. The object of the active sentence becomes the subject, and the original subject — the agent — moves to the end after “by”, but only when the agent is worth mentioning.",
     form:["Active: An intern wrote the report. → Passive: The report was written by an intern.","Affirmative: subject + was/were + past participle → The letters were sent yesterday.","Negative: wasn’t / weren’t + participle → It wasn’t signed by the manager.","Question: Was / Were + subject + participle? → Was the file deleted?","Wh-question: When was it published? / Who was it written by?"],
     notes:["Only verbs with an object can go into the passive. “Happen”, “arrive”, “go” and “die” have no passive form.","The tense lives in “be”, not in the participle: “was written” (past), “is written” (present), “will be written” (future).","Include “by + agent” only when the agent is new, surprising or important: “The bridge was designed by a local architect.” Otherwise drop it.","Irregular participles must be accurate — the passive exposes them: taken, written, built, sent, made, broken, done.","Keep the participle, not the past form: “was chose” is wrong; it is “was chosen”."],
     deep:"The passive is a spotlight, not a politeness device. Every sentence has a topic — the thing the sentence is about — and English puts that topic in the subject position. When the interesting thing is the object of the action, the passive lets you keep it at the front: in a paragraph about a building, “It was designed in 1912” keeps the building as the subject and preserves the flow. That is why the passive dominates reports, news and academic writing, and why translating everything into the active often makes a text choppier, not clearer. The one rule to internalise is that the tense is carried entirely by “be”. Learners who write “was wrote” have simply chosen the wrong second element; the past is already in “was”, so the second slot must be the participle. And the agent question is genuinely stylistic: leave out “by” when the agent is unknown, irrelevant or obvious (“the shop was robbed”, “taxes are collected annually”), and keep it when your reader would ask who.",
     chart:{title:"Active → past passive", cols:["Active","Passive","Agent needed?"], rows:[["Someone stole my bike.","My bike was stolen.","no — unknown"],["Bell invented the telephone.","The telephone was invented by Bell.","yes — important"],["They cancelled the meeting.","The meeting was cancelled.","no — obvious"],["A student wrote this.","This was written by a student.","yes — surprising"],["The storm damaged two houses.","Two houses were damaged by the storm.","yes — the cause"]]},
     examples:["The system was updated last night, so some settings were reset.","This photograph was taken by my grandfather in 1968.","Were you invited to the launch?","Nothing was decided at the meeting."],
     watch:"After was/were, use the past participle, not the past simple: “was taken”, never “was took”."},
    {name:"Passive without “by” (simple present)", short:"Coffee is grown here. Smoking isn’t allowed.",
     rule:"The present passive is formed with am / is / are plus the past participle. It is the normal way to describe processes, rules and general facts, and in most of these sentences the agent is deliberately omitted because it is unknown, obvious or unimportant.",
     form:["Affirmative: subject + am/is/are + past participle → Tickets are checked at the door.","Negative: isn’t / aren’t + participle → Dogs aren’t allowed inside.","Question: Is / Are + subject + participle? → Is breakfast included?","With modals: must be signed, can be found, should be kept.","Process sequence: First the beans are picked, then they are dried and sorted."],
     notes:["Rules and notices live in this structure: “Payment is required in advance”, “Helmets must be worn”.","In process descriptions, the agent is almost never mentioned — the sequence is the point, not the workers.","The subject and “be” must agree: “The documents are checked”, “The document is checked”.","Adverbs of frequency go between “be” and the participle: “Files are usually backed up at midnight.”","“Born” only exists in the passive: “I was born in 1998” — never “I borned”."],
     deep:"Present passives are the grammar of institutions. Signs, terms and conditions, manuals and procedure documents all use them because they describe what happens regardless of who does it, and because the anonymity is functional rather than evasive: nobody cares which member of staff checks the tickets. This is also why the passive is so useful when you describe a process — each step keeps the product as its subject, so the reader follows one thing through a chain of actions rather than tracking a cast of people. Two practical habits will improve your writing quickly. First, when you catch yourself writing a vague active subject — “they check the tickets”, “people say that” — consider a passive instead: “tickets are checked”, “it is said that”. Second, do not overshoot: if the actor is genuinely the point, the active is stronger and shorter. The passive earns its place when the actor is noise.",
     chart:{title:"When to omit the agent", cols:["Reason","Example","Agent"], rows:[["Unknown","My phone was stolen.","omitted"],["Obvious from context","The letters are delivered daily.","omitted (the postal service)"],["Irrelevant","Rooms are cleaned every morning.","omitted"],["General rule","Shoes must be removed.","omitted"],["Genuinely informative","The mural was painted by students.","kept with by"]]},
     examples:["The beans are picked by hand, washed, and then dried in the sun.","Mobile phones aren’t allowed during the exam.","Is service included in the price?","Applications are reviewed within ten working days."],
     watch:"“Born” has no active form: “I was born in Cali”, never “I born” or “I have born”."} ],
  speaking:[
    {kind:"Process talk", text:"Explain how something is made or done — coffee, a passport, a delivery — in six present-passive steps, with no agents."},
    {kind:"House rules", text:"In pairs, write the eight rules of a gym, a library or a shared flat using present passives with allowed, required, permitted and must be."},
    {kind:"Museum guide", text:"Describe five objects or buildings in your city in the past passive. Include “by” only where the agent genuinely matters."} ],
  tips:[
    "The tense sits in “be”; the second word is always a participle.",
    "Drop “by” unless your reader would ask who did it.",
    "Learn irregular participles in threes — the passive puts them on display."],
  quiz:{q:"This building ___ in 1904 by a Belgian architect.", options:["was designed","was design","is designed"], answer:0, explain:"A finished past event with a named agent takes was + past participle: “was designed by…”."} },

{ n:12, title:"TRACE", classes:"50–51", node:"node/12_trace", color:"#d9a13b", theme:"Background action, interrupted action, and effort still in progress",
  overview:{
    intro:"Two continuous tenses with two very different jobs. The past continuous paints the background of a story and gets interrupted by the simple past. The present perfect continuous measures an activity that started in the past and is still running, or has only just stopped.",
    goals:["Contrast the past continuous and the simple past in narration.","Form the present perfect continuous and use it with for, since, all day and lately.","Choose between the present perfect simple and continuous according to focus."],
    outcome:"By the end you can narrate an incident with background and interruption, and explain what you have been working on recently."
  },
  vocab:[
    {term:"to interrupt", pos:"verb", def:"to stop someone or something in the middle of an action.",
     use:"Transitive: “Sorry to interrupt you.” Noun: interruption. The past continuous is the tense that gets interrupted.",
     examples:["He interrupted me while I was speaking.","Sorry to interrupt, but there’s a call for you."],
     colloc:"constantly interrupt · sorry to interrupt · without interruption"},
    {term:"lately / recently", pos:"adverbs", def:"in the recent past, in a period still open.",
     use:"Both signal the present perfect (simple or continuous): “I’ve been sleeping badly lately.”",
     examples:["Have you seen him lately?","I’ve been travelling a lot recently."],
     colloc:"lately · until recently · just recently"},
    {term:"all day / all morning", pos:"time phrases", def:"for the whole of that period.",
     use:"Strong triggers for the present perfect continuous: “I’ve been working all day.”",
     examples:["It’s been raining all day.","I’ve been on calls all morning."],
     colloc:"all day long · all week · all this time"},
    {term:"to look into", pos:"phrasal verb", def:"to investigate something.",
     use:"Inseparable. Frequently in the continuous: “We’ve been looking into the problem.”",
     examples:["I’ll look into it this afternoon.","They’ve been looking into the cause for weeks."],
     colloc:"look into a matter · worth looking into"},
    {term:"progress", pos:"noun", def:"movement towards a goal.",
     use:"Noncount: “a lot of progress”, never “progresses”. “Make progress”, not “do progress”.",
     examples:["We’ve been making good progress.","There’s been little progress so far."],
     colloc:"make progress · slow progress · work in progress"},
    {term:"to deal with", pos:"phrasal verb", def:"to handle a problem or a person.",
     use:"Inseparable: “deal with it”. Past: dealt (pronounced “delt”).",
     examples:["I’ve been dealing with complaints all week.","Who deals with invoices here?"],
     colloc:"deal with a problem · hard to deal with"},
    {term:"exhausted", pos:"adjective", def:"extremely tired.",
     use:"A strong adjective, so no “very”: use “absolutely exhausted”. Often the result of a continuous activity.",
     examples:["I’m exhausted — I’ve been driving since six.","She looked exhausted after the shift."],
     colloc:"absolutely exhausted · mentally exhausted"},
    {term:"to keep an eye on", pos:"expression", def:"to watch something carefully over time.",
     use:"Fixed phrase with “on”: “Keep an eye on the server.” Often paired with continuous tenses.",
     examples:["We’ve been keeping an eye on the numbers.","Can you keep an eye on my bag?"],
     colloc:"keep an eye on it · keep a close eye on"},
    {term:"to go on", pos:"phrasal verb", def:"to continue; to happen.",
     use:"“How long has this been going on?” is the classic present perfect continuous question.",
     examples:["What’s going on here?","This has been going on for months."],
     colloc:"go on for hours · what’s going on · go on doing"},
    {term:"suddenly / just then", pos:"adverbs", def:"markers of the interrupting event in a story.",
     use:"They introduce the simple past that breaks into a past continuous: “I was leaving when suddenly the alarm went off.”",
     examples:["Just then, the lights went out.","Suddenly everyone started shouting."],
     colloc:"suddenly stop · just then · all of a sudden"} ],
  grammar:[
    {name:"Past continuous vs simple past", short:"I was cooking when the phone rang.",
     rule:"The past continuous (was/were + -ing) describes an action in progress at a past moment: the background. The simple past describes a completed action: the event. In a narrative, the simple past interrupts the past continuous.",
     form:["Past continuous: was / were + -ing → At eight I was still working.","Interruption pattern: past continuous + when + simple past → I was leaving when he called.","Parallel actions: while + past continuous, past continuous → While I was cooking, she was studying.","Negative / question: I wasn’t listening. / What were you doing at ten?"],
     notes:["“When” usually introduces the short, completed action; “while” usually introduces the longer, background one. That is why “I was reading when the light went out” and “While I was reading, the light went out” both work.","The past continuous sets scenes and moods in storytelling: “It was raining and nobody was talking.”","State verbs resist the continuous: know, believe, own, belong, want. Say “I knew”, not “I was knowing”.","Two past continuous clauses joined by “while” mean the actions overlapped completely.","The past continuous can also express an interrupted plan: “I was going to call you, but I fell asleep.”"],
     deep:"Narration in English is built on two layers, and the tenses keep them apart. The past continuous is the canvas — weather, feelings, activities already under way — and the simple past is the paint: the events that actually move the story forward. If you tell a story entirely in the simple past, everything sounds equally important; if you tell it entirely in the past continuous, nothing ever happens. Practise combining them in one sentence with “when”: background first, then the event. There is a subtlety worth noticing in the interrupted-plan use: “I was walking to the station when I saw her” tells you the walk was interrupted, not necessarily abandoned, while “I walked to the station and saw her” makes both events complete and sequential. Choosing the continuous is therefore a way of signalling that the action was in progress and possibly incomplete — a small tense choice carrying real narrative information.",
     chart:{title:"Background vs event", cols:["Pattern","Tenses","Example"], rows:[["Interruption","was -ing + when + past simple","I was sleeping when the alarm rang."],["Same, reversed","While + was -ing, past simple","While I was sleeping, the alarm rang."],["Two parallel actions","was -ing + while + was -ing","She was cooking while I was working."],["Sequence of events","past simple + past simple","I woke up, showered and left."],["Scene setting","was -ing (no interruption)","It was raining and the streets were empty."]]},
     examples:["I was crossing the street when a car came round the corner.","While we were waiting for the bus, it started to rain.","What were you doing when the power went out?","She wasn’t paying attention, so she missed the announcement."],
     watch:"Do not use the continuous with state verbs: “I was knowing him” is wrong — say “I knew him”."},
    {name:"Present perfect continuous", short:"I’ve been waiting for an hour.",
     rule:"The present perfect continuous (have/has been + -ing) links an activity to the present through its duration. It says how long something has been going on — either it is still happening, or it stopped so recently that the effects are visible.",
     form:["Affirmative: subject + have/has been + -ing → She’s been studying since eight.","Negative: haven’t / hasn’t been + -ing → I haven’t been sleeping well.","Question: Have you been waiting long? / How long has this been going on?","Duration markers: for two hours, since Monday, all day, lately, recently."],
     notes:["Use it for duration and activity; use the present perfect simple for completion and quantity: “I’ve been writing emails” (activity) vs “I’ve written six emails” (result).","Visible present evidence is a classic trigger: “Your eyes are red — have you been crying?”","State verbs stay simple: “I’ve known her for years”, never “I’ve been knowing”.","With “live”, “work” and “study” both forms are possible and mean almost the same: “I’ve lived / I’ve been living here for six years.”","“For” + duration, “since” + starting point — the same pairing you met at node 04."],
     deep:"This tense is where duration and relevance meet. The perfect part connects the action to now; the continuous part says the action had length and possibly still has. That combination is why it answers “how long?” so naturally and why it so often carries a note of effort or complaint: “I’ve been trying to reach you all morning” contains information about your patience as well as the facts. The clearest way to feel the contrast with the simple perfect is to look at what each one counts. The continuous counts time (“I’ve been reading for two hours”); the simple counts achievements (“I’ve read forty pages”). Both sentences can be true at the same moment, and choosing between them tells your listener whether you want to talk about your effort or your result. One trap: a recently finished activity with visible evidence uses the continuous even though the action has stopped — “It’s been raining” is what you say when the ground is wet and the sky has cleared.",
     chart:{title:"Simple or continuous perfect?", cols:["Focus","Form","Example"], rows:[["How long (still going)","have been -ing","I’ve been working here for two years."],["Recent activity with evidence","have been -ing","You’re dirty — have you been running?"],["Repeated activity lately","have been -ing","I’ve been going to the gym a lot lately."],["Completed result","have + participle","I’ve finished the report."],["How many / how much","have + participle","I’ve made three calls today."],["States","have + participle","I’ve known him since school."]]},
     examples:["I’ve been waiting for the technician since nine and nobody has come.","She’s been learning Portuguese for six months and she’s already reading novels.","Have you been working out? You look great.","We haven’t been getting many complaints lately."],
     watch:"Never combine the continuous with state verbs, and never with a counted result: “I’ve been writing three emails” should be “I’ve written three emails”."} ],
  speaking:[
    {kind:"Incident report", text:"Narrate a small accident or surprise. Set the scene in the past continuous, then interrupt it twice with the simple past."},
    {kind:"How long?", text:"Ask your partner six “How long have you been…?” questions. Every answer must contain “for” or “since” and a continuous form."},
    {kind:"Detective", text:"One student is a witness, the others ask “What were you doing at…?” for five specific times. The witness must stay consistent."} ],
  tips:[
    "“When” takes the short event, “while” takes the long background.",
    "Continuous counts time; simple counts results.",
    "State verbs never take a continuous form."],
  quiz:{q:"I ___ dinner when the lights went out.", options:["was making","made","have been making"], answer:0, explain:"The background action in progress takes the past continuous; the interruption takes the simple past."} },

{ n:13, title:"SIGNATURE", classes:"55–56", node:"node/13_signature", color:"#d94f45", theme:"Describing with participles and identifying with relative pronouns",
  overview:{
    intro:"How do you compress a whole clause into one word in front of a noun? Participles. And how do you attach a defining detail to a person or thing? Relative pronouns. This node covers the -ing / -ed adjective pair and the clauses introduced by who, that and which.",
    goals:["Distinguish present participles (-ing) from past participles (-ed) as adjectives.","Use who, that and which correctly for people and things.","Decide when the relative pronoun can be omitted."],
    outcome:"By the end you can describe people, films and situations precisely, and define anything with a relative clause instead of two short sentences."
  },
  vocab:[
    {term:"fascinating / fascinated", pos:"adjectives", def:"causing great interest / feeling great interest.",
     use:"-ing describes the cause, -ed describes the person: “a fascinating book”, “I was fascinated”.",
     examples:["It was a fascinating documentary.","I’m fascinated by how it works."],
     colloc:"absolutely fascinating · fascinated by"},
    {term:"confusing / confused", pos:"adjectives", def:"hard to understand / not understanding.",
     use:"The instructions are confusing; you are confused. Reversing them is the classic mistake.",
     examples:["The form was confusing, so everyone got confused.","I’m confused about the deadline."],
     colloc:"deeply confused · rather confusing · confused about"},
    {term:"disappointing / disappointed", pos:"adjectives", def:"worse than expected / feeling let down.",
     use:"“I was disappointed with the result” — the result was disappointing. Preposition: disappointed with / by / in.",
     examples:["The ending was disappointing.","She was disappointed with her score."],
     colloc:"deeply disappointed · a disappointing result"},
    {term:"exhausting / exhausted", pos:"adjectives", def:"making you very tired / feeling very tired.",
     use:"A day can be exhausting; you are exhausted. Both are strong, so avoid “very”.",
     examples:["It was an exhausting week.","I’m completely exhausted."],
     colloc:"physically exhausting · utterly exhausted"},
    {term:"broken", pos:"past participle as adjective", def:"not working, or in pieces.",
     use:"Past participles work as adjectives directly before nouns: “a broken screen”, “a locked door”, “a written agreement”.",
     examples:["There’s a broken window in the office.","My phone’s broken."],
     colloc:"badly broken · a broken promise · broken down"},
    {term:"relative", pos:"noun / adjective", def:"a family member; also “connected to something”.",
     use:"In grammar, “relative pronoun” means a word that relates a clause to a noun: who, that, which, whose.",
     examples:["A relative of mine lives there.","Relative clauses add information."],
     colloc:"a close relative · relatively easy"},
    {term:"whose", pos:"relative pronoun", def:"showing possession inside a relative clause.",
     use:"For people and things: “the man whose car was stolen”, “a company whose profits fell”. Never write “who’s”.",
     examples:["That’s the woman whose son works with me.","We use a system whose interface is terrible."],
     colloc:"whose name · whose fault"},
    {term:"in charge", pos:"expression", def:"having control or responsibility.",
     use:"Useful in defining clauses: “the person who is in charge of hiring”.",
     examples:["Who’s in charge here?","The man in charge wasn’t available."],
     colloc:"in charge of · put in charge"},
    {term:"reliable", pos:"adjective", def:"that you can trust to work or to behave well.",
     use:"For people, machines and sources: “a reliable colleague”, “a reliable source”. Opposite: unreliable.",
     examples:["We need a supplier who is reliable.","The old laptop isn’t reliable any more."],
     colloc:"highly reliable · a reliable source"},
    {term:"annoying", pos:"adjective", def:"making you slightly angry.",
     use:"The person or thing causing it is annoying; you are annoyed: “an annoying noise”, “I was annoyed”.",
     examples:["That notification sound is really annoying.","He was annoyed about the delay."],
     colloc:"deeply annoying · get annoyed"} ],
  grammar:[
    {name:"Participles as adjectives: present and past", short:"a boring film / a bored student",
     rule:"Present participles (-ing) used as adjectives describe the thing that causes a feeling or effect. Past participles (-ed) describe the person or thing that receives it. Past participles are also used to describe a state resulting from an action.",
     form:["-ing = cause: The film was boring. / an interesting idea / a tiring journey.","-ed = experiencer: I was bored. / interested in art / tired after the trip.","Past participle for a resulting state: a broken window, a locked door, a printed form.","Participle before the noun: a fascinating story · a written report.","Participle after the noun (reduced clause): the man standing at the door · the documents signed yesterday."],
     notes:["Only people (and animals) can be “-ed” in the emotional pair, because only they have feelings: a film cannot be bored.","When both are grammatical, the meaning changes completely: “I’m confusing” means you confuse other people.","Prepositions after -ed adjectives are fixed and worth memorising: interested IN, bored WITH/OF, worried ABOUT, surprised AT/BY, disappointed WITH.","Participles after a noun are shortened relative clauses: “the woman who is standing there” → “the woman standing there”.","Past participles as adjectives keep their irregular forms: broken, written, taken, frozen, hidden."],
     deep:"Once you see the pattern as cause versus effect, the whole family becomes predictable and you stop learning pairs one at a time. The -ing form points outward at the source of a feeling; the -ed form points inward at the experiencer. That is why “I am boring” is a self-criticism and “I am bored” is a complaint about the world. The second half of the topic is subtler and more useful for writing: participles let you compress. Any relative clause with “be” can shrink into a participle phrase — “the people who were waiting outside” becomes “the people waiting outside”, and “the report that was written by the auditor” becomes “the report written by the auditor”. Written English uses this constantly, and using it yourself immediately raises the density of your sentences. Just keep the participle next to the noun it describes: put it too far away and it attaches to the wrong thing, which is how sentences like “I saw the man walking down the street with a telescope” become jokes.",
     chart:{title:"Cause and experiencer", cols:["Cause (-ing)","Experiencer (-ed)","Fixed preposition"], rows:[["interesting","interested","interested in"],["boring","bored","bored with / of"],["confusing","confused","confused about"],["surprising","surprised","surprised at / by"],["worrying","worried","worried about"],["disappointing","disappointed","disappointed with"]]},
     examples:["The training was exhausting, and by five everyone was exhausted.","I’m interested in the position, but the description is confusing.","There’s a broken chair and a locked cabinet in the meeting room.","The candidate waiting outside has the strongest CV."],
     watch:"Things are -ing, people are -ed: “The lecture was boring, so I was bored.”"},
    {name:"Relative pronouns for people and things: who, that, which", short:"the woman who called · the file that disappeared",
     rule:"A defining relative clause tells you which person or thing you mean. “Who” is for people, “which” for things, and “that” for both in defining clauses. The pronoun replaces the subject or the object of the clause — and when it replaces the object, it can be left out.",
     form:["Subject pronoun (cannot be omitted): the man who works upstairs / the app that crashed.","Object pronoun (can be omitted): the man (who/that) I met / the app (that) I downloaded.","Things: the file which / that contains the data.","Possession: the colleague whose laptop was stolen.","Non-defining, with commas, no “that”: My manager, who lives nearby, cycles to work."],
     notes:["Never repeat the subject or object inside the clause: “the man who he called me” and “the book that I read it” are both wrong.","If a noun or pronoun follows the gap, the relative pronoun is an object and can be dropped: “the film I saw”.","In non-defining clauses (extra information, between commas) you must use who or which, never that.","“Where” replaces “in which” for places and “when” replaces “on which” for times: “the office where I work”, “the day when we met”.","Prepositions usually stay at the end in speech: “the person I spoke to”, not “the person to whom I spoke” (formal only)."],
     deep:"Relative clauses are the single most efficient upgrade available to an A2 writer, because they turn two thin sentences into one adult sentence: “I have a colleague. She speaks four languages.” becomes “I have a colleague who speaks four languages.” The mechanics come down to one question — is the relative pronoun doing the subject’s job or the object’s job in its own clause? If it is the subject, it must stay, because a clause without a subject collapses. If it is the object, the clause already has a subject and the pronoun becomes optional, which is why native speakers drop it constantly. The other half of the topic is punctuation, and it carries meaning rather than decoration. “My brother who lives in Bogotá” implies you have more than one brother and identifies him; “My brother, who lives in Bogotá,” implies you have one brother and adds a detail. Commas therefore change the facts, not just the rhythm.",
     chart:{title:"Choosing the relative pronoun", cols:["Refers to","Subject","Object","Omission possible?"], rows:[["person","who / that","who(m) / that","yes, as object"],["thing","which / that","which / that","yes, as object"],["possession","whose","whose","no"],["place","where","—","no"],["time","when","—","yes: the day we met"],["extra info (commas)","who / which","who(m) / which","no"]]},
     examples:["The technician who came yesterday fixed it in ten minutes.","This is the report that everyone is talking about.","The film I watched last night was disappointing.","My neighbour, whose dog barks all night, has finally moved out."],
     watch:"Do not add an extra pronoun inside the clause: “the book that I read it” must be “the book that I read”."} ],
  speaking:[
    {kind:"Definitions game", text:"Define ten words without saying them, using only relative clauses: “It’s a machine that…”, “It’s a person who…”. Your partner guesses."},
    {kind:"Reviews", text:"Review a film, a course and a restaurant. Each review must use two -ing adjectives and two -ed adjectives correctly."},
    {kind:"Who’s who", text:"Describe three people in the room using defining relative clauses only. The group identifies them."} ],
  tips:[
    "Things are -ing, people are -ed.",
    "Never repeat the subject or object inside a relative clause.",
    "Commas make a relative clause extra information — and then “that” is banned."],
  quiz:{q:"The presentation was ___ , so half the audience looked ___ .", options:["confusing / confused","confused / confusing","confusing / confusing"], answer:0, explain:"The presentation causes the feeling (-ing); the audience experiences it (-ed)."} },

{ n:14, title:"PERMISSIONS", classes:"59–60", node:"node/14_permissions", color:"#5b8def", theme:"How sure you are, and what you are allowed to do",
  overview:{
    intro:"Modals do two jobs in this node. First they measure certainty: from “it must be true” down through “it could be” to “it might not be”. Then they set the rules: what is permitted, what is required, and what is forbidden — the vocabulary of every workplace, airport and building in the world.",
    goals:["Express degrees of certainty with must, may, might and could, plus adverbs.","Ask for and give permission with can, may, could and be allowed to.","State obligation and prohibition accurately with have to, must, mustn’t and can’t."],
    outcome:"By the end you can speculate about an unclear situation at three levels of certainty, and explain the rules of a place without ambiguity."
  },
  vocab:[
    {term:"certain / certainty", pos:"adjective / noun", def:"completely sure.",
     use:"“I’m certain that…” or “It’s certain to happen”. Slightly stronger and more formal than “sure”.",
     examples:["I’m almost certain she left at five.","There’s no certainty about the date."],
     colloc:"absolutely certain · a degree of certainty"},
    {term:"probably", pos:"adverb", def:"very likely, but not certain.",
     use:"Position matters: after “be” but before other verbs — “He’s probably late”, “She probably knows”. With negatives it comes before “won’t”: “He probably won’t come.”",
     examples:["They’ll probably arrive after lunch.","She probably didn’t see the message."],
     colloc:"most probably · probably not"},
    {term:"perhaps / maybe", pos:"adverbs", def:"possibly.",
     use:"Both usually start the sentence: “Maybe he forgot.” “Maybe” is one word as an adverb; “may be” is a verb form.",
     examples:["Perhaps we should call first.","Maybe it’s a mistake."],
     colloc:"perhaps not · maybe later"},
    {term:"to be allowed to", pos:"expression", def:"to have permission.",
     use:"The tensed alternative to “can”: “We weren’t allowed to enter”, “You’ll be allowed to vote”.",
     examples:["Are we allowed to take photos?","I wasn’t allowed to leave early."],
     colloc:"not allowed to · allowed in · strictly not allowed"},
    {term:"prohibited / forbidden", pos:"adjectives", def:"not permitted, usually by a rule or law.",
     use:"Formal register, usually in the passive: “Smoking is strictly prohibited.”",
     examples:["Parking is prohibited here.","Photography is forbidden inside."],
     colloc:"strictly prohibited · legally forbidden"},
    {term:"obligation", pos:"noun", def:"something you must do.",
     use:"“Have an obligation to + verb”. The adjective “obligatory” means compulsory.",
     examples:["We have an obligation to report it.","Attendance is obligatory."],
     colloc:"a legal obligation · under no obligation"},
    {term:"to assume", pos:"verb", def:"to accept something as true without checking.",
     use:"Followed by a that-clause: “I assumed you knew.” Central to speculation.",
     examples:["I assumed the meeting was cancelled.","Don’t assume anything."],
     colloc:"safe to assume · a reasonable assumption"},
    {term:"evidence", pos:"noun", def:"facts that show something is true.",
     use:"Noncount: “some evidence”, “a piece of evidence”, never “evidences”.",
     examples:["There’s no evidence that he took it.","The evidence suggests otherwise."],
     colloc:"clear evidence · lack of evidence · based on evidence"},
    {term:"to be supposed to", pos:"expression", def:"expected to, according to a rule or an arrangement.",
     use:"“We’re supposed to wear ID.” In the past it often implies failure: “I was supposed to call her.”",
     examples:["You’re supposed to check in online.","We were supposed to start at nine."],
     colloc:"supposed to be · not supposed to"},
    {term:"unlikely", pos:"adjective", def:"probably not going to happen or be true.",
     use:"“It’s unlikely (that)…” or “be unlikely to + verb”: “He’s unlikely to agree.”",
     examples:["It’s unlikely that they’ll finish today.","An unlikely explanation."],
     colloc:"highly unlikely · unlikely to happen"} ],
  grammar:[
    {name:"Modals and adverbs for degrees of certainty", short:"It must be broken. It might be the cable. It can’t be the software.",
     rule:"When you deduce rather than know, English uses modals to show how sure you are. “Must” is a confident conclusion, “may / might / could” are open possibilities, and “can’t / couldn’t” is a confident negative conclusion. Adverbs do the same job in a different position.",
     form:["Near certainty (positive): must + base verb → She must be at lunch.","Possibility: may / might / could + base verb → It might be a network problem.","Near certainty (negative): can’t / couldn’t + base verb → He can’t be serious.","Adverbs: definitely, certainly, probably, possibly, maybe, perhaps → It’s definitely the cable.","Continuous form: must / might + be + -ing → They must be waiting outside."],
     notes:["The negative of deductive “must” is “can’t”, not “mustn’t”: “He can’t be at home” (deduction) vs “He mustn’t be at home” (prohibition).","“May not” and “might not” express a real possibility that something is untrue: “She might not know yet.”","“Could” in speculation means possible, but “can” does not: never “It can be the cable” for speculation.","Adverb position: “definitely / probably / certainly” go after “be” but before other verbs, and before a negative auxiliary — “He definitely isn’t coming.”","For deductions about the past, add “have + participle”: “She must have forgotten” — a preview of node 15."],
     deep:"Speculation is a scale, and modal verbs are the marks along it. At the top, “must” means you have evidence and have drawn a conclusion — not that you know for a fact, which is an important nuance: “She must be tired” actually means “I deduce she is tired.” In the middle, “may”, “might” and “could” are almost interchangeable, with “may” a little more formal and “could” a little more casual. At the bottom, English does something asymmetrical that catches learners out: the negative conclusion is not “mustn’t” but “can’t”, because “mustn’t” has already been claimed by prohibition. Keep the two ladders separate in your head — one for deduction (must / might / can’t), one for rules (must / can / mustn’t) — and remember that the same word can be on both ladders with different meanings, which is exactly why context and intonation do so much work in real speech.",
     chart:{title:"Certainty scale", cols:["How sure","Modal","Adverb","Example"], rows:[["100% (known)","—","definitely / certainly","It’s definitely the router."],["~90% (deduction)","must","almost certainly","It must be the router."],["~60%","should","probably","That should be the problem."],["~40%","may / might / could","maybe / perhaps / possibly","It might be the router."],["~10% negative","might not / may not","probably not","It might not be the router."],["~0% (deduction)","can’t / couldn’t","definitely not","It can’t be the router."]]},
     examples:["Nobody’s answering — they must be in the meeting.","It might be a permissions problem, or it could just be the cache.","That can’t be right; the numbers don’t add up.","She probably won’t reply before Monday."],
     watch:"For a negative deduction use “can’t”, not “mustn’t”: “He can’t be the manager” (I deduce he isn’t)."},
    {name:"Permission, obligation and prohibition", short:"You can park here. You have to pay. You mustn’t smoke.",
     rule:"Three separate ideas, three sets of forms. Permission uses can, may, could and be allowed to. Obligation uses must, have to, need to and be supposed to. Prohibition uses mustn’t, can’t and is not allowed to. The negatives are not interchangeable.",
     form:["Permission: You can / may use this room. / Are we allowed to record?","Asking permission: Can I…? Could I…? May I…? (most formal) / Would it be all right if I…?","Obligation: You must sign in. / You have to wear a badge. / Everyone needs to register.","No obligation: You don’t have to stay. / You needn’t worry.","Prohibition: You mustn’t open that. / You can’t park here. / Recording is not allowed."],
     notes:["“Don’t have to” = optional; “mustn’t” = forbidden. This distinction decides whether your rule makes sense.","“May” is the most formal permission form and appears in notices: “Visitors may use the side entrance.”","Only “have to”, “be allowed to” and “be supposed to” can change tense: “We weren’t allowed to enter”, “You’ll have to wait”.","“Can’t” often replaces “mustn’t” in speech for prohibition: “You can’t take photos in here.”","“Be supposed to” describes an expectation rather than a hard rule, and in the past it usually implies the rule was broken: “I was supposed to send it yesterday.”"],
     deep:"Rules are social, so the form you choose sends a message about your authority as well as the content of the rule. “You must submit the form” sounds like the speaker owns the rule; “you have to submit the form” sounds like they are reporting someone else’s; “you’re supposed to submit the form” sounds like a reminder that also leaves room for the fact that you did not. Learn the pairs by their negatives, because that is where meaning flips rather than fades — must / mustn’t, have to / don’t have to, can / can’t, be allowed to / not be allowed to. And note which forms are grammatically complete: true modals cannot conjugate, so any rule you need to put into the past or the future has to be expressed with “have to” or “be allowed to”. That is why real-world English uses those two far more than “must”, which survives mostly in written notices and in the deduction sense you met in the previous topic.",
     chart:{title:"Rules toolkit", cols:["Idea","Forms","Example"], rows:[["Permission","can / may / be allowed to","You may leave your bag here."],["Asking permission","Can I / Could I / May I","Could I use your phone?"],["Obligation","must / have to / need to","You have to show your ticket."],["No obligation","don’t have to / needn’t","You don’t have to book."],["Prohibition","mustn’t / can’t / not allowed to","You mustn’t use flash."],["Expectation","be supposed to","We’re supposed to arrive by nine."]]},
     examples:["You can bring a guest, but they have to sign in at reception.","You mustn’t leave the door open — it locks automatically.","Are we allowed to eat at our desks? — You can, but you don’t have to hide it.","We were supposed to finish by six, so we had to stay late."],
     watch:"“You don’t have to come” invites; “You mustn’t come” forbids. Choose carefully."} ],
  speaking:[
    {kind:"Speculation", text:"Look at three photos of unclear situations. Each student offers one deduction with “must”, one possibility with “might” and one rejection with “can’t”."},
    {kind:"Rules audit", text:"Choose a place you know. State ten rules using can, can’t, have to, don’t have to and mustn’t. The group flags any rule that is ambiguous."},
    {kind:"Permission role-play", text:"Ask your teacher, your boss and your best friend for the same favour, changing the level of formality each time."} ],
  tips:[
    "Two ladders: deduction (must / might / can’t) and rules (must / can / mustn’t).",
    "“Don’t have to” is freedom; “mustn’t” is prohibition.",
    "Only “have to” and “be allowed to” can move through the tenses."],
  quiz:{q:"The lights are off and the door is locked. They ___ have gone home.", options:["must","can’t","don’t have to"], answer:0, explain:"The evidence supports a confident conclusion, so “must” expresses the deduction."} },

{ n:15, title:"ROLLBACK", classes:"64–65", node:"node/15_rollback", color:"#2fbf9e", theme:"Imaginary situations and things you should have done differently",
  overview:{
    intro:"The unreal past, in two directions. The second conditional imagines a present or future that is not true, and past modals judge decisions that are already made. Both take a step back in tense to signal that we have left reality — the same move you learnt with “wish”.",
    goals:["Build second conditional sentences with if + past simple and would + base verb.","Use should have, shouldn’t have and would have to comment on past actions.","Distinguish real (first) from unreal (second) conditionals."],
    outcome:"By the end you can argue a hypothetical case (“if I were in charge…”) and review a past decision with regret, blame or justification."
  },
  vocab:[
    {term:"to regret", pos:"verb", def:"to feel sorry about something you did or didn’t do.",
     use:"“Regret + -ing” for the past action (“I regret sending it”); “regret + to inform” is a formal announcement of bad news.",
     examples:["I regret not taking that job.","We regret to inform you that the position is filled."],
     colloc:"deeply regret · no regrets · regret doing"},
    {term:"to blame", pos:"verb", def:"to say that someone is responsible for something bad.",
     use:"“Blame someone for something” or “blame something on someone”. “To be to blame” = to be responsible.",
     examples:["Don’t blame me for the delay.","Nobody was to blame."],
     colloc:"take the blame · blame it on · who’s to blame"},
    {term:"in your shoes", pos:"expression", def:"in your situation.",
     use:"The classic second conditional opener: “If I were in your shoes, I’d resign.”",
     examples:["If I were in your shoes, I’d wait.","I wouldn’t like to be in his shoes."],
     colloc:"in your shoes · put yourself in my shoes"},
    {term:"to turn down", pos:"phrasal verb", def:"to refuse an offer; also to reduce volume.",
     use:"Separable: “turn down the offer”, “turn it down”. Common in regret sentences.",
     examples:["I turned down the job and I still regret it.","Could you turn it down a bit?"],
     colloc:"turn down an offer · turn down the volume"},
    {term:"otherwise", pos:"adverb", def:"if not; in the other case.",
     use:"Links a condition to a consequence across two sentences: “Leave now; otherwise you’ll miss it.”",
     examples:["Write it down, otherwise you’ll forget.","She apologised; otherwise I would have complained."],
     colloc:"otherwise fine · or otherwise"},
    {term:"hypothetical", pos:"adjective", def:"imagined, not real.",
     use:"“A hypothetical situation” — the exact label for second conditional content. Noun: hypothesis.",
     examples:["Let’s take a hypothetical case.","That’s purely hypothetical."],
     colloc:"a hypothetical question · purely hypothetical"},
    {term:"to be worth it", pos:"expression", def:"justified by the result.",
     use:"Frequent in evaluating past decisions: “It wouldn’t have been worth it.”",
     examples:["The extra cost wasn’t worth it.","It would have been worth trying."],
     colloc:"worth the risk · not worth it"},
    {term:"to warn", pos:"verb", def:"to tell someone about a risk in advance.",
     use:"“I warned you” is the natural companion of “you should have listened”.",
     examples:["I warned you about that supplier.","They warned us not to click the link."],
     colloc:"warn someone about · fair warning"},
    {term:"lesson", pos:"noun", def:"something you learn from an experience.",
     use:"“Learn a lesson”, “that taught me a lesson”. Useful for closing a regret story.",
     examples:["It was an expensive lesson.","I learnt my lesson."],
     colloc:"a hard lesson · learn a lesson"},
    {term:"instead of", pos:"preposition", def:"in place of.",
     use:"Followed by a noun or -ing: “instead of waiting”, never an infinitive.",
     examples:["I should have called instead of sending an email.","Instead of complaining, do something."],
     colloc:"instead of that · rather than"} ],
  grammar:[
    {name:"Unreal conditional sentences with if clauses (second conditional)", short:"If I had more time, I would travel.",
     rule:"The second conditional describes an imaginary present or future: a situation that is not true, is unlikely, or is purely hypothetical. The if-clause takes the past simple, and the main clause takes would (or could / might) plus the base verb.",
     form:["If + past simple, would + base verb → If I earned more, I would move out.","Reversed: I would move out if I earned more.","With “to be”: If I were you… (were for all persons in careful English).","Other modals: If we left now, we could still catch it. / she might agree.","Negative: If I didn’t have to work, I wouldn’t stay in the city."],
     notes:["The past tense here is unreal, not past: “If I had a car” is about now.","“If I were you, I would…” is the standard way to give strong advice in English.","Never put “would” in the if-clause of a standard second conditional: “If I would have time” is wrong.","Contrast with the first conditional: “If it rains, I’ll stay in” (real possibility) vs “If it rained in July, everyone would be surprised” (unlikely).","“Could” in the main clause means ability or possibility; “might” means the result itself is uncertain."],
     deep:"Second conditionals are the grammar of argument and imagination, and they behave exactly like “wish”: one step back in tense equals one step away from reality. The past form is a marker of unreality, which is why “if I were” survives as a subjunctive form here even though English has lost most of its subjunctive elsewhere. Two practical uses make this structure worth mastering. First, advice: “if I were you” lets you tell someone what to do while explicitly acknowledging that you are not them, which is why it lands so much more gently than “you should”. Second, negotiation and speculation: “if we cut the budget, we would lose the third phase” puts a consequence on the table without committing to it. Keep the two conditionals distinct by asking whether you consider the condition realistic. If yes, use the first; if you are imagining, use the second. And keep “would” out of the if-clause — the only place it belongs is the result.",
     chart:{title:"First vs second conditional", cols:["","First conditional","Second conditional"], rows:[["Meaning","real, possible future","unreal or unlikely"],["If-clause","present simple","past simple"],["Main clause","will / going to","would / could / might"],["Example","If I get the job, I’ll move.","If I got the job, I’d move."],["With to be","If he is late, we’ll start.","If he were late, we’d start."],["Advice use","—","If I were you, I’d wait."]]},
     examples:["If I spoke better English, I would apply for that position.","What would you do if your laptop died the night before the deadline?","If I were you, I’d talk to her before Monday.","We could finish today if we didn’t have so many meetings."],
     watch:"No “would” after “if”: “If I had time, I would help” — never “If I would have time”."},
    {name:"Past modals: should have and would have", short:"I should have called. / I would have helped.",
     rule:"To comment on the past, English adds “have + past participle” to a modal. “Should have” expresses regret, criticism or an unfulfilled expectation. “Would have” expresses what was hypothetically possible in a past that did not happen — the result half of a third conditional.",
     form:["should have + participle → I should have booked earlier. (I didn’t.)","shouldn’t have + participle → You shouldn’t have said that. (You did.)","would have + participle → I would have helped, but nobody told me.","could have + participle → We could have won. (We didn’t.)","Third conditional: If I had known, I would have called."],
     notes:["The pattern is always modal + have + participle, never “should had” or “should of” — the last one is a spelling of the spoken contraction “should’ve” and is always wrong in writing.","“Should have” criticises the past; “should” alone advises the present: “You should call her” vs “You should have called her”.","“Would have” usually needs a condition, stated or implied: “I would have come (if I had known).”","“Must have” is deduction about the past (“she must have left”), not obligation — see node 14.","In speech these contract heavily: should’ve, would’ve, could’ve, must’ve. Train your ear for them."],
     deep:"Past modals let you talk about roads not taken, which is why they carry so much emotional weight. “I should have listened” admits fault. “You shouldn’t have told him” assigns it. “I would have helped” defends your intention against the facts. Structurally they are simple — the modal never changes, “have” never changes, and the only variable is the participle — but they are difficult to hear, because in real speech the whole cluster reduces to a single unstressed syllable. Training your ear here pays off twice: it fixes your listening and it stops you writing “should of”. Notice too how naturally they combine with the third conditional to complete the conditional system: node 09 gave you the real future, this node gives you the unreal present and the unreal past. “If I had left earlier, I would have caught the train” is the last piece — a fact that cannot be changed, discussed as if it could.",
     chart:{title:"Past modal meanings", cols:["Form","Reality","Meaning"], rows:[["I should have studied.","I didn’t.","regret"],["You shouldn’t have shouted.","You did.","criticism"],["I would have helped.","I didn’t (no chance).","unrealised intention"],["We could have won.","We didn’t.","missed possibility"],["She must have forgotten.","probably true.","past deduction"],["If I’d known, I’d have called.","I didn’t know.","third conditional"]]},
     examples:["I should have backed up the file before the update.","You shouldn’t have paid in cash — now there’s no record.","I would have told you, but your phone was off.","We could have avoided all this if we had read the contract."],
     watch:"Write “should have” (or “should’ve”), never “should of”, and never “should had”."} ],
  speaking:[
    {kind:"In your shoes", text:"Bring a real dilemma. Each classmate advises you with “If I were you, I’d…” and one “you should have…” about what led you here."},
    {kind:"Alternative lives", text:"Describe three hypothetical versions of your life with second conditionals. Your partner asks one follow-up question about each."},
    {kind:"Post-mortem", text:"In groups, review a failed plan (real or invented). Each person contributes one “should have”, one “could have” and one “would have”."} ],
  tips:[
    "Unreal = one step back in tense. Present unreal → past; past unreal → past perfect.",
    "“Would” lives in the result clause only.",
    "Modal + have + participle. Never “should of”."],
  quiz:{q:"If I ___ you, I wouldn’t sign anything today.", options:["were","am","would be"], answer:0, explain:"The second conditional takes a past form in the if-clause, and “were” is the standard form for all persons in “if I were you”."} },

{ n:16, title:"RELAY", classes:"68–69", node:"node/16_relay", color:"#d94f45", theme:"Passing on what other people said and asked for",
  overview:{
    intro:"The final node is about transmission: taking someone’s words and delivering them in your own. Reported speech shifts tenses back, changes pronouns and time words, and turns requests into infinitives. Master it and you can relay a conversation accurately, which is the highest-value skill in any workplace.",
    goals:["Report statements with said, told and that, applying the tense backshift.","Report requests and commands with asked / told + object + to + infinitive.","Adjust pronouns, time and place words when the context changes."],
    outcome:"By the end you can listen to a short conversation and report it accurately in three sentences, without quoting."
  },
  vocab:[
    {term:"to tell", pos:"verb", def:"to give information to a specific person.",
     use:"“Tell” always needs a person: “tell me”, “tell her”. Compare “say”, which does not: “She said that…”.",
     examples:["She told me she was leaving.","Tell them we’ll be late."],
     colloc:"tell the truth · tell someone about · tell a story"},
    {term:"to say", pos:"verb", def:"to speak words.",
     use:"“Say (that) + clause”, with no person, unless you add “to”: “He said to me that…” (less common).",
     examples:["He said he would call back.","What did she say?"],
     colloc:"say sorry · say nothing · as I said"},
    {term:"to mention", pos:"verb", def:"to say something briefly, without detail.",
     use:"“Mention that…” or “mention + noun”. No person object without “to”: “He mentioned it to me.”",
     examples:["She mentioned that the deadline moved.","Nobody mentioned the budget."],
     colloc:"briefly mention · not to mention · as mentioned"},
    {term:"to complain", pos:"verb", def:"to say you are unhappy about something.",
     use:"“Complain (to someone) about something” or “complain that…”. Common in reported speech.",
     examples:["He complained that the room was too cold.","She complained to HR about the schedule."],
     colloc:"complain about · a formal complaint"},
    {term:"to insist", pos:"verb", def:"to say something firmly and repeatedly.",
     use:"“Insist on + -ing” or “insist that + clause”: “She insisted on paying.”",
     examples:["He insisted that he had sent it.","She insisted on seeing the manager."],
     colloc:"insist on · strongly insist"},
    {term:"to admit", pos:"verb", def:"to accept that something bad is true.",
     use:"“Admit + -ing” or “admit that…”: “He admitted making a mistake.” Never an infinitive.",
     examples:["She admitted that she had forgotten.","He admitted breaking the rule."],
     colloc:"admit a mistake · freely admit"},
    {term:"to promise", pos:"verb", def:"to say you will definitely do something.",
     use:"“Promise to + verb” or “promise that…”: “He promised to send it today.”",
     examples:["They promised to call back within an hour.","She promised she wouldn’t tell anyone."],
     colloc:"break a promise · keep a promise"},
    {term:"to refuse", pos:"verb", def:"to say no to something.",
     use:"“Refuse to + verb”, never -ing: “He refused to sign.” Noun: refusal.",
     examples:["She refused to give her name.","They refused our request."],
     colloc:"flatly refuse · refuse to accept"},
    {term:"to remind", pos:"verb", def:"to make someone remember something.",
     use:"“Remind someone to + verb” (a task) or “remind someone about + noun”. Not the same as “remember”, which is your own memory.",
     examples:["Remind me to send the invoice.","She reminded us about the meeting."],
     colloc:"remind me to · a gentle reminder"},
    {term:"apparently", pos:"adverb", def:"according to what people say; it seems.",
     use:"A useful way to report information you have not verified: “Apparently they’re closing the office.”",
     examples:["Apparently, the flight was cancelled.","She’s leaving, apparently."],
     colloc:"apparently not · apparently so"} ],
  grammar:[
    {name:"Reported speech: statements", short:"“I’m tired.” → She said she was tired.",
     rule:"When you report what someone said, the verb usually moves one tense back, the pronouns change to your point of view, and time and place words shift to match your situation. “Say” takes no personal object; “tell” requires one.",
     form:["Present → past: “I work here.” → He said he worked there.","Present continuous → past continuous: “I’m waiting.” → She said she was waiting.","Past simple → past perfect: “I saw it.” → He said he had seen it.","will → would; can → could; must → had to → “I’ll call.” → She said she would call.","Structure: said (that) + clause / told + person + (that) + clause."],
     notes:["“That” is optional after both verbs: “She said (that) she was busy.”","No backshift is necessary when the information is still true or the reporting is immediate: “She says she’s on her way.”","Pronouns and possessives shift with the speaker: “I lost my keys” → He said he had lost his keys.","Time and place words shift too: now → then, today → that day, tomorrow → the next day, here → there, this → that.","“Say” cannot take a person directly: “He said me” is wrong; use “He told me” or “He said to me”."],
     deep:"Reported speech looks like a table of transformations, but underneath it there is a single logic: you are re-anchoring the utterance to your own here and now. The original speaker’s present is in your past, so the tense moves back; their “I” is your “he”; their “tomorrow” may already be yesterday by the time you report it. Once you think of it as re-anchoring rather than memorising, the exceptions make sense too — if nothing has moved (you are reporting a general truth, or the words were spoken a minute ago) then nothing needs to shift: “She says the office closes at six.” The past perfect deserves a note: it is the end of the road backwards, so a past simple and a past perfect original both report as a past perfect, and in relaxed speech many speakers leave a past simple unchanged when the sequence is already clear. Finally, choose your reporting verb deliberately. “Said”, “told”, “explained”, “admitted”, “complained” and “insisted” report the same words while telling your listener what kind of act it was — and that choice is often more informative than the words themselves.",
     chart:{title:"Backshift table", cols:["Direct speech","Reported speech","Example"], rows:[["present simple","past simple","“I live here.” → She said she lived there."],["present continuous","past continuous","“I’m working.” → He said he was working."],["past simple","past perfect","“I called.” → She said she had called."],["present perfect","past perfect","“I’ve finished.” → He said he had finished."],["will","would","“I’ll help.” → She said she would help."],["can / must","could / had to","“I can’t come.” → He said he couldn’t come."]]},
     examples:["“The system is down.” → The technician said the system was down.","“I’ll send it tomorrow.” → She told me she would send it the next day.","“I didn’t receive your email.” → He said he hadn’t received my email.","“We’re still hiring.” → They say they’re still hiring. (still true, no backshift)"],
     watch:"“Say” never takes a person object: “She told me…” or “She said that…”, never “She said me…”."},
    {name:"Reported speech: requests and commands", short:"“Please wait.” → She asked me to wait.",
     rule:"Requests, orders and advice are not reported with a that-clause but with an object plus an infinitive. The reporting verb carries the force: asked (request), told (order), advised, reminded, warned, invited, begged.",
     form:["Request: asked + object + to + verb → She asked me to wait outside.","Order: told + object + to + verb → He told us to be quiet.","Negative: asked / told + object + not to + verb → She asked me not to call after nine.","Other verbs: advised / reminded / warned / invited / encouraged + object + to + verb.","Reported questions: asked + if / whether or wh-word, with statement order → He asked if I was free. / She asked where I lived."],
     notes:["The negative goes before “to”: “not to be late”, never “to not be late” in careful English.","These verbs all need a personal object: “She asked to wait” means she wanted to wait herself, which is a different meaning.","Reported questions lose their inversion and their “do”: “Where do you work?” → She asked where I worked.","“Say” cannot report a request: “He said me to wait” is wrong — use “told me to wait”.","Choose the verb for the force of the original: “told” sounds like an order, “asked” like a request, “begged” like desperation."],
     deep:"This structure is where reported speech becomes genuinely useful, because most of what we relay in working life is not information but instructions. The infinitive pattern is elegantly economical: “She asked me to resend the invoice” contains the speaker, the addressee, the action and the social force of the original in eight words. The single most common error is dropping the object — English insists on knowing who was asked — and the second is choosing a verb that misrepresents the force, which can create real friction: reporting your colleague’s polite “could you check this?” as “he told me to check it” makes them sound rude. Note the parallel with reported questions, which drop inversion and auxiliaries in exactly the way indirect questions did at node 02; the same principle is at work, because an embedded clause is never a question in its own right. Together, these two topics close the level: you can now carry other people’s words, requests and questions across time and person without quoting them.",
     chart:{title:"Reporting different speech acts", cols:["Original","Type","Report"], rows:[["“Please wait here.”","request","She asked me to wait there."],["“Be quiet!”","order","He told us to be quiet."],["“Don’t touch it.”","prohibition","She told me not to touch it."],["“You should rest.”","advice","He advised me to rest."],["“Are you free?”","yes/no question","She asked if I was free."],["“Where do you live?”","wh-question","He asked where I lived."]]},
     examples:["“Could you send the file again?” → She asked me to send the file again.","“Don’t forget the deadline.” → He reminded us not to forget the deadline.","“Have you finished?” → She asked whether I had finished.","“Come to the meeting at four.” → They invited me to come to the meeting at four."],
     watch:"Requests need an object and an infinitive: “asked me to wait”. And the negative is “not to”, never “to not”."} ],
  speaking:[
    {kind:"Relay", text:"In threes: A whispers three sentences to B, B reports them to C, C checks the original. Score one point per accurate backshift."},
    {kind:"Message board", text:"Take four phone messages from your partner and report them to the class: two statements, one request, one question."},
    {kind:"Gossip control", text:"Report the same statement with three different verbs (said, complained, insisted) and discuss how the meaning changes."} ],
  tips:[
    "Report by re-anchoring: tense back one step, pronouns to your point of view, time words to your clock.",
    "“Tell” needs a person, “say” does not.",
    "Requests take “asked/told + object + to + verb”, and the negative is “not to”."],
  quiz:{q:"“Please don’t tell anyone.” → She asked me ___ anyone.", options:["not to tell","to not tell","don’t tell"], answer:0, explain:"Reported requests use “asked + object + to + infinitive”, and the negative goes before “to”: not to tell."} }
);
